#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

int main() {
    pthread_mutexattr_t attr;
    int pshared_value;
    int ret;

    // 1. Initialize the mutex attributes object
    if ((ret = pthread_mutexattr_init(&attr)) != 0) {
        fprintf(stderr, "Error initializing attributes: %d\n", ret);
        return 1;
    }

    // 2. Set the process-shared attribute to PTHREAD_PROCESS_SHARED
    printf("Attempting to set mutex sharing scope to PTHREAD_PROCESS_SHARED...\n");
    if ((ret = pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED)) != 0) {
        fprintf(stderr, "Error setting shared attribute: %d\n", ret);
        // Clean up before exit
        pthread_mutexattr_destroy(&attr);
        return 1;
    }

    // 3. Verify the setting using the get function
    if ((ret = pthread_mutexattr_getpshared(&attr, &pshared_value)) != 0) {
        fprintf(stderr, "Error retrieving shared attribute: %d\n", ret);
        pthread_mutexattr_destroy(&attr);
        return 1;
    }

    // 4. Report the result
    if (pshared_value == PTHREAD_PROCESS_SHARED) {
        printf("Verification successful: Mutex scope is set for inter-process sharing.\n");
    } else {
        printf("Verification failed or unexpected result.\n");
    }

    // 5. Clean up attributes object
    if ((ret = pthread_mutexattr_destroy(&attr)) != 0) {
        fprintf(stderr, "Error destroying attributes: %d\n", ret);
        return 1;
    }

    return 0;
}
